import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from Simple Icons (CC0) "planetscale".
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "light"
  },
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "dark"
  }
];

import {
  accountRouter,
  array,
  decodeJson,
  defineApp,
  defineProvider,
  oauth2,
  object,
  query,
  renameTools,
  router,
  secrets,
  string,
  withApprovals,
  type AccountOf,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";
import { operationNamespaces, operationScopes, scopeAliases, serviceTokenOnly } from "./scopes.js";

// Keep this provider declaration unchanged so saved accounts keep their provider identity,
// response projection, requested scopes and saved OAuth grants.
const planetscale = defineProvider({
  name: "PlanetScale",
  hosts: ["api.planetscale.com", "app.planetscale.com", "auth.planetscale.com"],
  auth: {
    token: secrets({
      label: "Service token",
      fields: object({
        // Sent verbatim as the Authorization header.
        token: string({ minLength: 3 }),
      }),
    }),
    oauth2: oauth2({
      discover: "https://api.planetscale.com",
      scopes: [
        "read_user",
        "read_organization",
        "write_organization",
        "read_databases",
        "write_databases",
        "organization:create_databases",
        "organization:delete_databases",
        "organization:read_databases",
        "organization:write_databases",
        "organization:read_branches",
        "organization:write_branches",
        "organization:delete_branches",
        "organization:read_deploy_requests",
        "organization:write_deploy_requests",
        "organization:approve_deploy_requests",
        "organization:deploy_deploy_requests",
        "organization:read_comments",
        "organization:write_comments",
        "organization:read_backups",
        "organization:write_backups",
        "organization:delete_backups",
        "organization:restore_backups",
        "organization:manage_passwords",
        "organization:manage_read_only_passwords",
        "organization:read_members",
        "organization:read_workflows",
        "organization:write_workflows",
        "organization:read_audit_logs",
      ],
    }),
  },
  async health({ account, fetch, signal }) {
    const authorization =
      account.method === "oauth2" ? `Bearer ${account.fields.access_token}` : account.fields.token;
    const response = await fetch("https://api.planetscale.com/v1/organizations?per_page=1", {
      signal,
      headers: { Authorization: authorization, Accept: "application/json" },
    });
    const list = await decodeJson(
      response,
      object({ data: array(object({ id: string(), name: string() })) }),
    );
    const organization = list.data[0];
    if (!organization) throw new Error("PlanetScale credential has access to no organizations");
    return { accountInfo: { externalId: organization.id, username: organization.name } };
  },
});

// New sign-ins use a separate provider so changing the requested scopes and projecting the
// returned grant cannot invalidate accounts saved under `planetscale`.
const planetscaleSignIn = defineProvider({
  name: "PlanetScale",
  hosts: ["api.planetscale.com", "app.planetscale.com", "auth.planetscale.com"],
  auth: {
    signIn: oauth2({
      discover: "https://api.planetscale.com",
    }),
  },
  async health({ account, fetch, signal }) {
    const response = await fetch("https://api.planetscale.com/v1/organizations?per_page=1", {
      signal,
      headers: { Authorization: `Bearer ${account.fields.access_token}`, Accept: "application/json" },
    });
    const list = await decodeJson(
      response,
      object({ data: array(object({ id: string(), name: string() })) }),
    );
    const organization = list.data[0];
    if (!organization) throw new Error("PlanetScale credential has access to no organizations");
    return { accountInfo: { externalId: organization.id, username: organization.name } };
  },
});

type LegacyAccount = AccountOf<typeof planetscale>;
type SignInAccount = AccountOf<typeof planetscaleSignIn>;
type Account = LegacyAccount | SignInAccount;

/** Expand the aliases PlanetScale advertises so either spelling is checked against an operation. */
const grantOf = (account: Account) => {
  const value = account.oauthScopes;
  if (value === undefined) return undefined;
  const scopes = new Set(value);
  for (const [short, long] of Object.entries(scopeAliases)) {
    if (scopes.has(short)) scopes.add(long);
    if (scopes.has(long)) scopes.add(short);
  }
  return scopes;
};

/** Known grant metadata reports capabilities independently of legacy discovery compatibility. */
const scopeAllows = (account: Account, name: string) => {
  const grant = grantOf(account);
  if (grant === undefined) return true;
  return operationScopes[name]?.some((scope) => grant.has(scope)) ?? false;
};

/** Unknown legacy and DCR grants keep the old listing; PlanetScale still authorizes each call. */
const offers = (account: Account, grantAware: boolean, name: string) =>
  !grantAware || account.method !== "signIn" || scopeAllows(account, name);

export default defineApp(
  {
    user: {
      accounts: {
        planetscaleSignIn: planetscaleSignIn.many(),
        planetscale: planetscale.many(),
      },
    },
    icons,
  },
  async ({ user, cache, fetch, signal }) => {
    const tools = (account: Account, grantAware: boolean, serviceTokenAliases = false) => {
      const openapi = {
        ...options,
        cache,
        fetch,
        signal,
        // The API document calls its OAuth security scheme `oauth2`, independently of our method name.
        account: account.method === "signIn" ? { ...account, method: "oauth2" } : account,
      };
      return withApprovals(
        renameTools(liveOpenapiRouter(openapi), (name) => {
          if (serviceTokenAliases) return serviceTokenOnly.has(name) ? name : undefined;
          return offers(account, grantAware, name) ? name : undefined;
        }),
        (tool) => (tool.kind === "mutation" ? always() : undefined),
      );
    };
    const legacy = user?.accounts.planetscale ?? [];
    const signIns = user?.accounts.planetscaleSignIn ?? [];
    const selections = [
      ...legacy.map((account) => ({
        id: account.id,
        discover: () => tools(account, false),
      })),
      ...signIns.map((account) => ({
        id: account.id,
        discover: () => tools(account, true),
      })),
    ];
    const root = await accountRouter(selections, (selection) => selection.discover(), { signal });
    const connected = [...legacy, ...signIns];
    const namespaceHasTools = (namespace: string) =>
      connected.some((account) =>
        [...Object.keys(operationScopes), ...serviceTokenOnly].some(
          (name) => name.startsWith(`${namespace}.`) && offers(account, account.method === "signIn", name),
        ),
      );
    const namespacedRoot = Object.fromEntries(
      operationNamespaces
        .filter(namespaceHasTools)
        .map((namespace) => [
          namespace,
          renameTools(root, (name) =>
            name.startsWith(`${namespace}.`) ? name.slice(namespace.length + 1) : undefined,
          ),
        ]),
    );
    const serviceToken = await accountRouter(
      legacy.filter((account) => account.method === "token"),
      (account) => tools(account, false, true),
      { signal },
    );

    return {
      tools: router(
        {
          ...namespacedRoot,
          serviceToken: router(serviceToken, {
            title: "PlanetScale service-token tools",
            description:
              "Operations PlanetScale documents as service-token-only. PlanetScale checks which permissions the token has.",
          }),
          permissions: query(
            {
              input: object({}),
              description:
                "OAuth scopes recorded by the host for each account, including equivalent names. Missing scope data is unknown; PlanetScale decides access to each resource.",
            },
            async () =>
              connected.map((account) => {
                const reported = account.oauthScopes;
                const known = reported !== undefined;
                return {
                  accountId: account.id,
                  method:
                    account.method === "token"
                      ? "service token"
                      : account.method === "oauth2"
                        ? "legacy OAuth"
                        : "PlanetScale sign-in",
                  permissions: known
                    ? [...reported].sort()
                    : "Unknown: PlanetScale did not report this account's permissions.",
                  unavailableTools: known
                    ? [
                        ...Object.keys(operationScopes).filter((name) => !scopeAllows(account, name)),
                        ...[...serviceTokenOnly].map((name) => `serviceToken.${name}`),
                      ]
                    : null,
                };
              }),
          ),
        },
        {
          title: "PlanetScale",
          description:
            "PlanetScale organizations, databases, branches, deploy requests, backups, passwords, workflows and Insights.",
          icons,
        },
      ),
    };
  },
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// The document declares only oauth2 globally. Service tokens go in the Authorization header as
// "<service token id>:<service token>", so the global security is removed and replaced by a fallback accepting either.
export const options = {
  source: { url: "https://planetscale.com/docs/openapi.yaml" },
  allowedOrigin: "https://api.planetscale.com",
  securitySchemes: {
    oauth2: {
      type: "oauth2",
      flows: {
        authorizationCode: {
          authorizationUrl: "https://app.planetscale.com/oauth/authorize",
          tokenUrl: "https://auth.planetscale.com/oauth/token",
          scopes: {},
        },
      },
    },
    serviceToken: { type: "apiKey", name: "Authorization", in: "header" },
  },
  methods: { token: [{ scheme: "serviceToken", field: "token", part: "value", prefix: "" }] },
  oauth: ["oauth2"],
  patches: [{ op: "remove", path: "/security" }],
  fallbackSecurity: [{ oauth2: [] as string[] }, { serviceToken: [] as string[] }] as { [x: string]: string[] }[],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/planetscale",
  "description": "PlanetScale organizations, databases, branches, deploy requests, backups, passwords, workflows and Insights through the PlanetScale API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "PlanetScale"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.14"
  }
}
